/// Re-reads allowed when the cursor readback disagrees with the requested position,
/// and the pause between them. Bounded because the agent serves one command at a
/// time — an unbounded settle loop would stall all actuation on a display where the
/// cursor never reaches the requested point.
const MAX_POSITION_REREADS: u32 = 3;
const POSITION_REREAD_INTERVAL_MS: u64 = 50;

/// Re-reads allowed for a command whose cursor arrives asynchronously — see
/// `Plan::pointer_arrival_is_deferred`, which means a Windows `drag` or `move`.
///
/// Two arrival profiles share this budget, and the larger one sets it. A non-smooth
/// drag's cursor reaches its destination 110-166ms after the command file is written.
/// But with `CC_SMOOTH_MOVE` set, `mouse_control.ahk`'s `GlideTo` paces the pointer
/// along a minimum-jerk curve whose duration is capped at 900ms (`SMOOTH_MAX_MS` there),
/// and the agent writes the file and returns while the watcher is still gliding — so a
/// smooth `move` or `drag` does not finish arriving until ~900ms plus one 10ms watcher
/// poll after the write. The last re-read must fall past that, or a glide that landed
/// perfectly reports `X=?`.
///
/// 20 re-reads at 50ms put the last read at ~1s (plus the 20ms settle already elapsed),
/// clearing the 910ms worst case with margin. If the glide cap in the `.ahk` ever rises,
/// this must rise with it; the two are pinned together by `glide_budget_covers_ahk_cap`.
///
/// It costs nothing on the common path: re-reads happen only while the position still
/// disagrees, so a command that verifies immediately pays none of them, and only a
/// command that would otherwise have reported an unverified coordinate waits longer.
const DEFERRED_POSITION_REREADS: u32 = 20;

/// The glide-duration ceiling in `assets`/`watcher_scripts` `mouse_control.ahk`
/// (`SMOOTH_MAX_MS`). Named here so the readback budget above can be checked against it.
#[cfg(test)]
const AHK_GLIDE_MAX_MS: u64 = 900;

/// Notches a scroll command performs when it names no count. Every backend applies
/// this same number — macos_actuation.py and linux_actuation.py resolve it when they
/// build the command, mouse_control.ahk when it reads one — so the agent can state it
/// in the record for a command that omitted it.
///
/// The four must not drift apart: the agent would then report a count the backend did
/// not perform. `test_scroll_default_count_is_the_same_on_every_backend` reads all
/// four and fails if any one moves.
const DEFAULT_SCROLL_NOTCHES: u32 = 5;

// Mouse position data structure
#[derive(Debug, Clone)]
struct MousePosition {
    x: i32,
    y: i32,
    /// The coordinate was read back from the display and matched what was asked.
    captured: bool,
    /// `x`/`y` mean something. A requested-but-unverified point sets this with
    /// `captured` false; a command that produced no coordinate at all sets
    /// neither. Without the distinction the two collapse into `(0, 0)`, and the
    /// wire could not tell "the pointer was asked to go here and could not be
    /// read back" from "there is no position", which is why a move over a
    /// native-Wayland surface reported nothing at all.
    known: bool,
}

/// A mouse button the agent has pressed and not yet released.
///
/// `X Y hold` issues a button-down with no timeout. Without this, an unmatched hold
/// leaves the button physically down: every later click or move is interpreted as a
/// drag-select, and the console reports plain success throughout.
#[derive(Debug, Clone)]
struct HeldButton {
    /// Where the button went down, when the command named a coordinate.
    ///
    /// `here hold` names none. Substituting (0, 0) for "unknown" would make the
    /// automatic release move the cursor to the top-left corner first — dragging
    /// whatever is grabbed to the origin on the way out, which is worse than the
    /// stuck button it is meant to fix. Unknown releases in place instead.
    at: Option<(i32, i32)>,
    since: std::time::Instant,
}

// Detailed action information
#[derive(Debug, Clone)]
struct ActionDetails {
    action_type: String,  // "left", "right", "double", "drag", etc.
    is_mouse: bool,
    is_here_command: bool,
    /// Modifier keys held for the duration of a pointer action, resolved to this
    /// platform's display names ("Cmd", "Option", …). Empty for every other command.
    ///
    /// Kept separate from `action_type` so the verb match stays exact: a Cmd-click is
    /// a click, and only the record's wording differs. Folding the prefix into the
    /// verb would drop the action out of `is_mouse` and record a pointer gesture as
    /// typed text.
    modifiers: Vec<String>,
}

/// Agent implementation
pub struct AgentServiceImpl {
    os_type: OsType,
    os_version: String,
    capabilities: Vec<String>,
    #[cfg(target_os = "macos")]
    cliclick_path: Option<String>,
    /// Buttons pressed and not yet released, keyed by button name. Populated from
    /// the validated argv, never from the caller-supplied human_command, because it
    /// drives an automatic release at shutdown.
    held_buttons: Arc<RwLock<HashMap<String, HeldButton>>>,
}

/// Core implementation of the AgentService
impl AgentServiceImpl {
    pub fn new() -> Self {
        let (os_type, os_version) = Self::detect_os_version();
        let capabilities = Self::detect_capabilities(&os_type);
        
        info!("Agent initialized with position tracking");
        info!("  OS: {:?}", os_type);
        info!("  Version: {}", os_version);
        info!("  Capabilities: {:?}", capabilities);
        
        Self {
            os_type,
            os_version,
            capabilities,
            #[cfg(target_os = "macos")]
            cliclick_path: Self::resolve_cliclick_path(),
            held_buttons: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    #[cfg(target_os = "macos")]
    fn resolve_cliclick_path() -> Option<String> {
        let paths = [
            "/usr/local/bin/cliclick",
            "/opt/homebrew/bin/cliclick",
            "cliclick",
        ];
        for p in &paths {
            if ProcessCommand::new(p).arg("--version").output().is_ok() {
                return Some(p.to_string());
            }
        }
        None
    }
    
    /// Real OS detection with version information
    fn detect_os_version() -> (OsType, String) {
        #[cfg(target_os = "windows")]
        {
            Self::detect_windows_version()
        }
        
        #[cfg(target_os = "macos")]
        {
            Self::detect_macos_version()
        }
        
        #[cfg(target_os = "linux")]
        {
            Self::detect_linux_version()
        }
    }
    
    /// Windows version detection using registry
    #[cfg(target_os = "windows")]
    fn detect_windows_version() -> (OsType, String) {
        use winreg::enums::*;
        use winreg::RegKey;
        
        let hklm = RegKey::predef(HKEY_LOCAL_MACHINE);
        
        if let Ok(current_version) = hklm.open_subkey("SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion") {
            let product_name: String = current_version.get_value("ProductName").unwrap_or_else(|_| "Windows".to_string());
            let display_version: String = current_version.get_value("DisplayVersion").unwrap_or_else(|_| String::new());
            let current_build: String = current_version.get_value("CurrentBuild").unwrap_or_else(|_| String::new());
            
            let version = if !display_version.is_empty() && !current_build.is_empty() {
                format!("{} {} (Build {})", product_name, display_version, current_build)
            } else if !current_build.is_empty() {
                format!("{} (Build {})", product_name, current_build)
            } else {
                product_name
            };
            
            return (OsType::Windows, version);
        }
        
        (OsType::Windows, "Windows (Unknown Version)".to_string())
    }
    
    /// Linux version detection using /etc/os-release and fallback methods
    #[cfg(target_os = "linux")]
    fn detect_linux_version() -> (OsType, String) {
        use std::fs;
        // Try /etc/os-release first (systemd standard)
        if let Ok(content) = fs::read_to_string("/etc/os-release") {
            let mut pretty_name = None;
            
            for line in content.lines() {
                if line.starts_with("PRETTY_NAME=") {
                    pretty_name = Some(
                        line.split('=')
                            .nth(1)
                            .unwrap_or("")
                            .trim_matches('"')
                            .to_string()
                    );
                    break;
                }
            }
            
            if let Some(name) = pretty_name {
                return (OsType::Linux, name);
            }
        }
        
        // Fallback: try lsb_release command
        if let Ok(output) = ProcessCommand::new("lsb_release").arg("-d").output() {
            if let Ok(description) = String::from_utf8(output.stdout) {
                if let Some(version) = description.split(':').nth(1) {
                    return (OsType::Linux, version.trim().to_string());
                }
            }
        }
        
        // Last resort: try uname
        if let Ok(output) = ProcessCommand::new("uname").arg("-sr").output() {
            if let Ok(version) = String::from_utf8(output.stdout) {
                return (OsType::Linux, version.trim().to_string());
            }
        }
        
        (OsType::Linux, "Linux (Unknown Distribution)".to_string())
    }
    
    /// macOS version detection using sw_vers
    #[cfg(target_os = "macos")]
    fn detect_macos_version() -> (OsType, String) {
        // Get macOS version using sw_vers
        if let Ok(output) = ProcessCommand::new("sw_vers").arg("-productVersion").output() {
            if let Ok(version) = String::from_utf8(output.stdout) {
                let version = version.trim();
                
                // Get build number
                if let Ok(build_output) = ProcessCommand::new("sw_vers").arg("-buildVersion").output() {
                    if let Ok(build) = String::from_utf8(build_output.stdout) {
                        return (
                            OsType::Macos,
                            format!("macOS {} (Build {})", version, build.trim())
                        );
                    }
                }
                
                return (OsType::Macos, format!("macOS {}", version));
            }
        }
        
        (OsType::Macos, "macOS (Unknown Version)".to_string())
    }
    
    /// Detect available capabilities
    fn detect_capabilities(os_type: &OsType) -> Vec<String> {
        let mut capabilities = vec!["mouse".to_string(), "keyboard".to_string(), "position_tracking".to_string()];
        
        match os_type {
            OsType::Windows => {
                capabilities.push("file_based_control".to_string());
            }
            OsType::Macos => {
                // Check if cliclick is available
                if ProcessCommand::new("which").arg("cliclick").output().is_ok() {
                    capabilities.push("cliclick".to_string());
                } else {
                    warn!("cliclick not found - install with: brew install cliclick");
                }
            }
            OsType::Linux => {
                // Check if xdotool is available
                if ProcessCommand::new("which").arg("xdotool").output().is_ok() {
                    capabilities.push("xdotool".to_string());
                } else {
                    warn!("xdotool not found - install with: sudo apt-get install xdotool");
                }
            }
        }
        
        capabilities
    }
    
    // Modifier symbol → this platform's display name. One table, so a chord and a
    // modifier-held pointer action name the same key the same way.
    fn modifier_names(&self) -> &'static [(&'static str, &'static str)] {
        match self.os_type {
            OsType::Macos   => &[("#", "Cmd"),   ("!", "Option"), ("^", "Ctrl"), ("+", "Shift")],
            OsType::Windows => &[("#", "Win"),   ("!", "Alt"),    ("^", "Ctrl"), ("+", "Shift")],
            OsType::Linux   => &[("#", "Super"), ("!", "Alt"),    ("^", "Ctrl"), ("+", "Shift")],
        }
    }

    // Split a modifier prefix off a pointer action token: "#left" → (["Cmd"], "left").
    //
    // A token that is nothing but modifiers ("#") keeps its prefix and is returned
    // whole, so it fails the `is_mouse` match below rather than being read as a verb
    // with no name. The controller cannot emit that form; this is what stops a
    // malformed one from being recorded as a successful gesture.
    fn split_mouse_modifiers(&self, token: &str) -> (Vec<String>, String) {
        let table = self.modifier_names();
        let mut names: Vec<String> = Vec::new();
        let mut rest = token;

        while let Some(ch) = rest.chars().next() {
            let sym = &rest[..ch.len_utf8()];
            match table.iter().find(|(s, _)| *s == sym) {
                Some((_, name)) => {
                    // Deduplicated, order preserved: "#+left" reads "Cmd+Shift+…" the
                    // way it was typed, matching how a chord is rendered.
                    if !names.iter().any(|n| n == name) {
                        names.push((*name).to_string());
                    }
                    rest = &rest[ch.len_utf8()..];
                }
                None => break,
            }
        }

        if names.is_empty() || rest.is_empty() {
            return (Vec::new(), token.to_string());
        }
        (names, rest.to_string())
    }

    // Convert a key string with modifiers into a human-readable format
    fn format_keys_for_display(&self, keys: &str) -> String {
        let mod_names = self.modifier_names();

        let special_name = |k: &str| -> Option<&'static str> {
            match k {
                "{Enter}" | "{Return}" => Some("Return"),
                "{Tab}"                => Some("Tab"),
                "{Esc}" | "{Escape}"   => Some("Esc"),
                "{Backspace}" | "{BS}" => Some("Delete"),
                "{Delete}" | "{Del}"   => Some("Fwd Delete"),
                "{Space}"              => Some("Space"),
                "{Up}"                 => Some("Up"),
                "{Down}"               => Some("Down"),
                "{Left}"               => Some("Left"),
                "{Right}"              => Some("Right"),
                "{Home}"               => Some("Home"),
                "{End}"                => Some("End"),
                "{PgUp}"               => Some("Page Up"),
                "{PgDn}"               => Some("Page Down"),
                "{F1}"  => Some("F1"),  "{F2}"  => Some("F2"),
                "{F3}"  => Some("F3"),  "{F4}"  => Some("F4"),
                "{F5}"  => Some("F5"),  "{F6}"  => Some("F6"),
                "{F7}"  => Some("F7"),  "{F8}"  => Some("F8"),
                "{F9}"  => Some("F9"),  "{F10}" => Some("F10"),
                "{F11}" => Some("F11"), "{F12}" => Some("F12"),
                _       => None,
            }
        };

        // Fast path: whole string is a bare special key
        if let Some(name) = special_name(keys) {
            return name.to_string();
        }

        let modifier_syms: &[char] = &['#', '!', '^', '+'];
        let mut parts: Vec<String> = Vec::new();
        let mut byte_pos = 0usize;

        for ch in keys.chars() {
            if !modifier_syms.contains(&ch) { break; }
            let sym = &keys[byte_pos..byte_pos + ch.len_utf8()];
            if let Some((_, name)) = mod_names.iter().find(|(s, _)| *s == sym) {
                parts.push(name.to_string());
            }
            byte_pos += ch.len_utf8();
        }

        let key_part = &keys[byte_pos..];
        if !key_part.is_empty() {
            if let Some(name) = special_name(key_part) {
                parts.push(name.to_string());
            } else if let Some(code) = key_part
                .strip_prefix("{code:")
                .and_then(|c| c.strip_suffix('}'))
                .filter(|c| c.chars().all(|ch| ch.is_ascii_digit()) && !c.is_empty())
            {
                // Keycode passthrough. Rendering the raw "code:21" here would put it
                // in the recorded step text, so give it a readable name.
                parts.push(format!("Key {}", code));
            } else if let Some(inner) = key_part
                .strip_prefix('{')
                .and_then(|k| k.strip_suffix('}'))
                .filter(|inner| !inner.contains('}'))
            {
                // Only a single brace token unwraps. An explicit down/up sequence
                // such as "{Ctrl down}s{Ctrl up}" also starts with '{' and ends with
                // '}', and stripping its outer braces yielded "Ctrl down}s{Ctrl up" —
                // a string with an unbalanced brace that no downstream parser can
                // read back as key tokens. Left whole it stays parseable.
                parts.push(inner.to_string());
            } else if key_part.chars().count() == 1 {
                parts.push(key_part.to_uppercase());
            } else {
                parts.push(key_part.to_string());
            }
        }

        if parts.is_empty() { keys.to_string() } else { parts.join("+") }
    }

    fn parse_action_details(&self, command: &str) -> ActionDetails {
        let tokens: Vec<&str> = command.split_whitespace().collect();

        let is_here = tokens.get(0) == Some(&"here");

        // The pointer verb may carry a modifier prefix ("770 310 #left"). It is split
        // off rather than matched as part of the verb: a Cmd-click is still a click,
        // and an unsplit "#left" falls out of `is_mouse` below and records the gesture
        // as typed text.
        let (modifiers, action_type) = if tokens.len() >= 3 && tokens[0].parse::<i32>().is_ok() {
            // Coordinate-based: "960 540 left", "770 310 #left"
            self.split_mouse_modifiers(tokens[2])
        } else if is_here && tokens.len() >= 2 {
            // Here command: "here left", "here hold", "here +left"
            self.split_mouse_modifiers(tokens[1])
        } else {
            let bare = if tokens.first() == Some(&"position") {
                "position"
            } else if tokens.first() == Some(&"press") {
                // "press {Enter}", "press ^c" — keyboard, not mouse
                "press"
            } else if command.contains("click") {
                "click"
            } else if command.contains("drag") {
                "drag"
            } else if command.contains("type") || command.contains("key") {
                "keyboard"
            } else {
                "unknown"
            };
            (Vec::new(), bare.to_string())
        };

        let is_mouse = matches!(
            action_type.as_str(),
            "left" | "right" | "middle" | "double" | "triple"
            | "click" | "drag" | "move"
            // scroll_left/scroll_right are macOS-only verbs, but they are verbs the
            // controller emits: without them here a horizontal scroll was recorded as
            // "Typed: 960 540 scroll_left 3".
            | "scroll_up" | "scroll_down" | "scroll_left" | "scroll_right"
            | "hold" | "release"     // mouse button hold/release
            | "position"             // position query
        );

        ActionDetails {
            action_type,
            is_mouse,
            is_here_command: is_here,
            modifiers,
        }
    }
    
    // Capture mouse position after execution
    async fn capture_mouse_position(&self) -> MousePosition {
        match self.os_type {
            OsType::Linux => self.capture_position_linux().await,
            OsType::Windows => self.capture_position_windows().await,
            OsType::Macos => self.capture_position_macos().await,
        }
    }
    
    /// The actuation binary for this session's display server.
    ///
    /// Every Linux path that names a binary goes through here: the readback in
    /// `capture_position_linux` and the uncommanded release in `release_argv`.
    /// That is the point of it being one function. The readback used to name
    /// xdotool unconditionally, so on Wayland the agent actuated through the
    /// portal helper and then read the position with a different program - one
    /// that reports nothing at all while the pointer is over a native-Wayland
    /// surface, making every move report an uncaptured position.
    ///
    /// `release_argv` had the same defect and outlived the first fix, which is
    /// why the selection is now a single function rather than a rule applied
    /// twice: a button pressed by the portal cannot be released by xdotool, so
    /// the shutdown release did nothing while reporting that it had, and the
    /// portal daemon does not expire while a button is held. A button left down
    /// corrupts every step of whatever runs next.
    ///
    /// The signals are the same ones LinuxActuation.detect_backend reads, and they
    /// have to stay the same: two independent detectors would disagree exactly
    /// when it mattered.
    /// Whether the position reader can tell a live reading from a stale one.
    ///
    /// Only the Wayland helper can. It emits `POSITION_VERIFIED=0` when XWayland is
    /// stuck over a native-Wayland surface, which `capture_position_linux` turns
    /// into `captured: false` — so for that reader a captured read is already known
    /// to be live. Every other reader here — xdotool, cliclick, the Windows
    /// registry — reports `captured: true` whenever a value parsed at all, which
    /// says the read succeeded and nothing about whether it is current.
    ///
    /// Takes the backend rather than reading the environment so the decision is a
    /// pure function of it: the caller passes `linux_backend()`, keeping one
    /// detector, and this stays testable without mutating process environment in a
    /// parallel test runner.
    fn reader_reports_staleness(backend: &str) -> bool {
        backend == "cc-wayland-actuate"
    }

    fn linux_backend() -> &'static str {
        #[cfg(target_os = "linux")]
        {
            let wayland = std::env::var("XDG_SESSION_TYPE")
                .map(|t| t.eq_ignore_ascii_case("wayland"))
                .unwrap_or(false)
                || std::env::var("WAYLAND_DISPLAY").is_ok();
            if wayland {
                return "cc-wayland-actuate";
            }
        }
        "xdotool"
    }

    #[cfg(target_os = "linux")]
    async fn capture_position_linux(&self) -> MousePosition {
        // Direct spawn with DISPLAY supplied via the environment. The agent invokes no
        // shell anywhere, so there is no interpreter for any input to reach.
        let display = std::env::var("DISPLAY").unwrap_or_else(|_| ":0".to_string());
        match ProcessCommand::new(Self::linux_backend())
            .args(["getmouselocation", "--shell"])
            .env("DISPLAY", display)
            .output()
        {
            Ok(output) if output.status.success() => {
                let stdout = String::from_utf8_lossy(&output.stdout);
                let x_regex = Regex::new(r"X=(\d+)").unwrap();
                let y_regex = Regex::new(r"Y=(\d+)").unwrap();
                
                if let (Some(x_cap), Some(y_cap)) = (x_regex.captures(&stdout), y_regex.captures(&stdout)) {
                    if let (Ok(x), Ok(y)) = (x_cap[1].parse::<i32>(), y_cap[1].parse::<i32>()) {
                        // POSITION_VERIFIED is emitted only by the Wayland helper,
                        // which can hand back a coordinate derived from its own
                        // motion when the X reader is stuck over a native-Wayland
                        // window. Absent (xdotool, and every older reader) means
                        // the value was measured, so the default is verified and
                        // nothing that existed before changes behaviour.
                        let verified = !stdout.contains("POSITION_VERIFIED=0");
                        debug!("Position read: ({}, {}) verified={}", x, y, verified);
                        return MousePosition { x, y, captured: verified, known: true };
                    }
                }
            }
            _ => {}
        }
        MousePosition { x: 0, y: 0, captured: false, known: false }
    }
    
    #[cfg(target_os = "windows")]
    async fn capture_position_windows(&self) -> MousePosition {
        use winreg::enums::{HKEY_CURRENT_USER, KEY_READ};
        use winreg::RegKey;

        let hkcu = RegKey::predef(HKEY_CURRENT_USER);
        if let Ok(key) = hkcu.open_subkey_with_flags("Software\\MouseTracker", KEY_READ) {
            if let (Ok(x_str), Ok(y_str)) = (
                key.get_value::<String, _>("MouseX"),
                key.get_value::<String, _>("MouseY"),
            ) {
                if let (Ok(x), Ok(y)) = (x_str.parse::<i32>(), y_str.parse::<i32>()) {
                    debug!("Position captured from registry: ({}, {})", x, y);
                    return MousePosition { x, y, captured: true, known: true };
                }
            }
        }

        MousePosition { x: 0, y: 0, captured: false, known: false }
    }
    
    #[cfg(target_os = "macos")]
    async fn capture_position_macos(&self) -> MousePosition {
        let cliclick_paths = ["/usr/local/bin/cliclick", "/opt/homebrew/bin/cliclick", "cliclick"];
        
        for cliclick_path in &cliclick_paths {
            if let Ok(output) = ProcessCommand::new(cliclick_path).arg("p:.").output() {
                if output.status.success() {
                    let stdout = String::from_utf8_lossy(&output.stdout).trim().to_string();
                    let parts: Vec<&str> = stdout.split(',').collect();
                    
                    if parts.len() == 2 {
                        if let (Ok(x), Ok(y)) = (parts[0].parse::<i32>(), parts[1].parse::<i32>()) {
                            debug!("Position captured: ({}, {})", x, y);
                            return MousePosition { x, y, captured: true, known: true };
                        }
                    }
                }
            }
        }
        MousePosition { x: 0, y: 0, captured: false, known: false }
    }
    
    // Cross-compilation stubs
    #[cfg(not(target_os = "linux"))]
    async fn capture_position_linux(&self) -> MousePosition {
        MousePosition { x: 0, y: 0, captured: false, known: false }
    }
    
    #[cfg(not(target_os = "windows"))]
    async fn capture_position_windows(&self) -> MousePosition {
        MousePosition { x: 0, y: 0, captured: false, known: false }
    }
    
    #[cfg(not(target_os = "macos"))]
    async fn capture_position_macos(&self) -> MousePosition {
        MousePosition { x: 0, y: 0, captured: false, known: false }
    }
    
    // Build detailed message with action and position
    fn build_detailed_message(
        &self,
        action: &ActionDetails,
        position: &MousePosition,
        command: &str,
    ) -> String {
        // Keyboard actions
        if action.action_type == "press" {
            let keys = command.trim_start_matches("press").trim();
            return format!("Pressed: {}", self.format_keys_for_display(keys));
        }
        if action.action_type == "keyboard" {
            // "type x.ai/careers" → "Typed: x.ai/careers"
            let content = command.trim_start_matches("type").trim();
            return format!("Typed: {}", content);
        }
        if !action.is_mouse {
            return format!("Typed: {}", command);
        }

        // Position query
        if action.action_type == "position" {
            return if position.captured {
                format!("Position: X={}, Y={}", position.x, position.y)
            } else {
                "Position: (?, ?)".to_string()
            };
        }

        // Mouse actions that don't need position
        if !position.captured {
            return format!("Executed: {}", command);
        }

        // Scroll renders its own line, because the notch count is part of the gesture
        // and the record has to carry it. Without it "here scroll_down 5" and
        // "here scroll_down 1" stored the same string, so a captured scroll step could
        // not be replayed from the record and S074 had to be re-recorded.
        //
        // The count is already here — `command` is the command as issued — so nothing
        // new crosses the wire. It is read from the position the controllers already
        // parse it from: after the verb, which is token 2 for `here` and token 3 for
        // the coordinate form.
        if let Some(direction) = action.action_type.strip_prefix("scroll_") {
            let tokens: Vec<&str> = command.split_whitespace().collect();
            let count_index = if action.is_here_command { 2 } else { 3 };
            let count = tokens
                .get(count_index)
                .and_then(|t| t.parse::<u32>().ok());

            let prefix = if action.modifiers.is_empty() {
                String::new()
            } else {
                format!("{}+", action.modifiers.join("+"))
            };

            // A bare `scroll_down` still scrolls DEFAULT_SCROLL_NOTCHES, so the record
            // states that number rather than omitting it. This sentence is the only
            // surviving description of the gesture — the command as typed is not
            // persisted downstream — so an omission here is not restraint, it is the
            // count being lost for good.
            //
            // It also decouples the record from the tool that replays it: a bare
            // scroll recorded against a backend whose default was 3 replays as 5 once
            // the defaults are aligned, and nothing in a countless record reveals the
            // change. An explicit count pins the step to what actually happened.
            let count = count.unwrap_or(DEFAULT_SCROLL_NOTCHES);
            return match count {
                1 => format!(
                    "{}Scrolled {} 1 notch at X={}, Y={}",
                    prefix, direction, position.x, position.y
                ),
                n => format!(
                    "{}Scrolled {} {} notches at X={}, Y={}",
                    prefix, direction, n, position.x, position.y
                ),
            };
        }

        // Mouse actions with position
        let action_name = match action.action_type.as_str() {
            "left"         => "Left-clicked",
            "right"        => "Right-clicked",
            "middle"       => "Middle-clicked",
            "double"       => "Double-clicked",
            "triple"       => "Triple-clicked",
            // `click` is the controller's alias for `left` and builds the identical
            // argv, so it must record identically too. Without this arm it fell to the
            // generic case below and the same gesture recorded as "Performed action",
            // which names no button and no click — a worse record for the operator who
            // used the documented alias.
            "click"        => "Left-clicked",
            "drag"         => "Dragged",
            "move"         => "Moved cursor to",
            "hold"         => "Held button at",
            "release"      => "Released button at",
            // No trailing preposition: the format strings below supply "at X=…", and
            // "Performed action at" produced "Performed action at at X=".
            _              => "Performed action",
        };

        // "Cmd+Left-clicked at …". A modifier held during a pointer action is part of
        // the gesture — a Cmd-click adds to a selection where a plain click replaces
        // it — so a record that drops it describes something that did not happen.
        let action_name = if action.modifiers.is_empty() {
            action_name.to_string()
        } else {
            format!("{}+{}", action.modifiers.join("+"), action_name)
        };

        // A drag renders its own line, because the record has to carry the whole path.
        // Three shapes were losing part of it, all of them the S074 failure again —
        // a step that cannot be replayed from its own record:
        //
        //   `here drag 900 700`      returned from the is_here_command branch and
        //                            recorded "Dragged at X=…", one point, reading
        //                            like a stationary action. Destination lost.
        //   `x y drag via … to …`    failed the integer parse on the `via` token and
        //                            fell through to a destination-only string.
        //                            Origin lost.
        //   both forms               never recorded the waypoints at all, so a
        //                            path-dependent drag could not be reproduced.
        //
        // The points are read from `command`, which is the command as issued, so
        // nothing new crosses the wire. The origin is deliberately omitted rather than
        // guessed for the `here` form: that form starts wherever the cursor already
        // is, the pre-command read is not available here, and a "from" taken from the
        // post-drag readback would name the destination twice.
        if action.action_type == "drag" {
            let (origin, waypoints, destination) =
                Self::parse_drag_path(command, action.is_here_command);
            let mut out = action_name;
            if let Some((x, y)) = origin {
                out.push_str(&format!(" from X={}, Y={}", x, y));
            }
            for (x, y) in waypoints {
                out.push_str(&format!(" via X={}, Y={}", x, y));
            }
            match destination {
                Some((x, y)) => out.push_str(&format!(" to X={}, Y={}", x, y)),
                // The command named no destination this could read. The readback is
                // then the only surviving evidence of where the drag ended.
                None => out.push_str(&format!(" to X={}, Y={}", position.x, position.y)),
            }
            return out;
        }

        format!("{} at X={}, Y={}", action_name, position.x, position.y)
    }

    /// The points a drag command names: its origin (absent for the `here` form, which
    /// starts from wherever the cursor already is), any `via` waypoints in order, and
    /// its destination.
    ///
    /// Reads the grammar the controllers build from — `<x2> <y2> [dwell <ms>]` or
    /// `via <ax> <ay> [via …] to <x2> <y2> [dwell <ms>]` — so the record cannot
    /// disagree with the gesture about which points were visited. A trailing
    /// `dwell <ms>` is timing rather than geometry and is not part of the path.
    fn parse_drag_path(
        command: &str,
        is_here: bool,
    ) -> (Option<(i32, i32)>, Vec<(i32, i32)>, Option<(i32, i32)>) {
        let tokens: Vec<&str> = command.split_whitespace().collect();

        let pair = |a: Option<&&str>, b: Option<&&str>| -> Option<(i32, i32)> {
            match (
                a.and_then(|t| t.parse::<i32>().ok()),
                b.and_then(|t| t.parse::<i32>().ok()),
            ) {
                (Some(x), Some(y)) => Some((x, y)),
                _ => None,
            }
        };

        // The verb sits at index 1 for `here`, index 2 for the coordinate form, and
        // the path follows it. The coordinate form's leading pair is the origin.
        let (verb_index, origin) = if is_here {
            (1, None)
        } else {
            (2, pair(tokens.first(), tokens.get(1)))
        };

        let mut rest: &[&str] = tokens.get(verb_index + 1..).unwrap_or(&[]);
        if rest.len() >= 2 && rest[rest.len() - 2] == "dwell" {
            rest = &rest[..rest.len() - 2];
        }

        let mut waypoints = Vec::new();
        let mut i = 0;
        while rest.get(i) == Some(&"via") {
            match pair(rest.get(i + 1), rest.get(i + 2)) {
                Some(point) => waypoints.push(point),
                None => break,
            }
            i += 3;
        }
        if rest.get(i) == Some(&"to") {
            i += 1;
        }

        (origin, waypoints, pair(rest.get(i), rest.get(i + 1)))
    }
    
    // Capture mouse position after a successful mouse action, verifying it against
    // the position the command asked for.
    //
    // A bare readback is not evidence. It can return the position from before the
    // command (the read raced the synthetic event) or the position the cursor never
    // left (the warp silently failed — reproducible on an X display with no mapped
    // window, where xdotool exits 0 and moves nothing). Either way the old code
    // reported `captured: true`, and that one value is both the operator's
    // step-gating signal and the coordinate stored in the training corpus.
    //
    // So: read, compare against the request, and re-read a bounded number of times
    // before giving up. Never report a coordinate that disagrees with the command —
    // `position_captured: false` is the honest answer and the schema already carries
    // it. The loop is capped because the agent serves one command at a time.
    async fn capture_position_if_mouse(
        &self,
        action: &ActionDetails,
        ok: bool,
        expected: Option<argv_policy::ExpectedPos>,
        before: Option<MousePosition>,
        deferred_arrival: bool,
    ) -> MousePosition {
        if !(action.is_mouse && ok) {
            return MousePosition { x: 0, y: 0, captured: false, known: false };
        }

        // A short pause before the first readback so the common case is a single
        // read. It is not the correctness mechanism — the loop below is, and it was
        // added after this constant was chosen. With a verify-and-retry loop behind
        // it, a settle long enough to cover the worst case just taxes every command
        // that did not need it; a settle short enough to occasionally read early
        // costs one 50ms re-read on those, and nothing on the rest.
        //
        // Measured on the Linux harness, interleaved 50/10/50/10 to keep the machine
        // state comparable, 60 moves into a mapped window per run:
        //   50ms settle -> p50 74.9 / 73.3ms, p95 91.1 / 87.7ms, 60/60 captured
        //   10ms settle -> p50 25.2 / 27.4ms, p95 43.1 / 42.5ms, 60/60 captured
        // No run at 10ms lost a capture, so the shorter settle is not being paid for
        // in re-reads. Windows is left alone: it was already 20/10ms.
        #[cfg(target_os = "windows")]
        let settle_ms = if action.is_here_command { 10 } else { 20 };
        #[cfg(not(target_os = "windows"))]
        let settle_ms = 10;

        tokio::time::sleep(tokio::time::Duration::from_millis(settle_ms)).await;
        let mut position = self.capture_mouse_position().await;

        // Commands that name no coordinate — "here left", "here hold", "position" —
        // do not move the cursor. That invariant is what they can be checked against:
        // a read taken before the command and one taken after must agree. If they do
        // not, something moved the cursor across the sample and neither value
        // describes the action, so report nothing rather than pick one.
        //
        // Without this these commands kept the old behaviour of publishing whatever
        // the readback returned as `captured: true` — the same unverified report the
        // coordinate path was fixed for, and `position` is exactly the command an
        // operator runs to obtain coordinates for the next step.
        let Some(want) = expected else {
            // `position` is a query, not an action: it reports where the pointer is
            // and changes nothing. The before/after equality check below exists
            // because a stale reader returns a plausible wrong value that a single
            // read cannot tell from a still mouse. Where the reader says so itself,
            // that check adds nothing and costs the answer: moving the mouse while
            // asking where it is returned "X=?, Y=?". Measured against the
            // compositor's cursor metadata, which updates about eleven times a
            // second, so a moving pointer makes the two samples differ nearly every
            // time.
            //
            // The exemption is gated on the reader, not on the verb, because the
            // premise is a property of the reader. It first shipped ungated, which
            // was wrong on X11: xdotool never emits POSITION_VERIFIED, so
            // `captured` is unconditionally true there and the check being skipped
            // was the only staleness signal `position` had - it names no coordinate,
            // so there is nothing else to compare a reading against. Measured with
            // the cursor moved 15229 times/sec: every `position` still claimed a
            // captured coordinate, while `here left` on the same run correctly
            // reported none.
            //
            // `here left`, `here hold` and the rest keep the check on every backend.
            // They act at whatever point the pointer occupies, so two disagreeing
            // samples mean the action landed somewhere neither of them names.
            if action.action_type == "position"
                && position.captured
                && Self::reader_reports_staleness(Self::linux_backend())
            {
                return position;
            }
            let Some(before) = before.filter(|p| p.captured) else {
                // No verified pre-read, so the "it must not have moved" check
                // cannot run. That rules out claiming a capture - it does not rule
                // out reporting anything at all. The backend may still know where
                // the pointer is from the motion it emitted, and `position` is the
                // command an operator runs precisely to obtain a coordinate.
                // Report it unverified; discarding it produced "X=?, Y=?" on the
                // one command whose entire purpose is to answer that question.
                return if position.known {
                    MousePosition { captured: false, ..position }
                } else {
                    MousePosition { x: 0, y: 0, captured: false, known: false }
                };
            };
            for _ in 0..MAX_POSITION_REREADS {
                if position.captured && position.x == before.x && position.y == before.y {
                    return position;
                }
                tokio::time::sleep(tokio::time::Duration::from_millis(
                    POSITION_REREAD_INTERVAL_MS,
                ))
                .await;
                position = self.capture_mouse_position().await;
            }
            if position.captured && position.x == before.x && position.y == before.y {
                return position;
            }
            warn!(
                "Cursor moved across a command that should not move it ({} at ({}, {}) \
                 before, {} after). Reporting position_captured=false.",
                action.action_type,
                before.x,
                before.y,
                if position.captured {
                    format!("({}, {})", position.x, position.y)
                } else {
                    "no read".to_string()
                }
            );
            return MousePosition { x: 0, y: 0, captured: false, known: false };
        };

        let rereads = if deferred_arrival {
            DEFERRED_POSITION_REREADS
        } else {
            MAX_POSITION_REREADS
        };
        for attempt in 0..rereads {
            if position.captured && position.x == want.x && position.y == want.y {
                return position;
            }
            debug!(
                "Position readback {:?} != requested ({}, {}), re-read {}/{}",
                (position.x, position.y), want.x, want.y, attempt + 1, rereads
            );
            tokio::time::sleep(tokio::time::Duration::from_millis(
                POSITION_REREAD_INTERVAL_MS,
            ))
            .await;
            position = self.capture_mouse_position().await;
        }

        if position.captured && position.x == want.x && position.y == want.y {
            return position;
        }

        warn!(
            "Position readback did not settle: requested ({}, {}), last read {}. \
             Reporting the requested coordinate with position_captured=false; over a \
             native-Wayland surface nothing can read the pointer, so this is the \
             requested point, not an observed one.",
            want.x,
            want.y,
            if position.captured {
                format!("({}, {})", position.x, position.y)
            } else {
                "none".to_string()
            }
        );
        // The requested point travels with captured=false. Discarding it as (0,0)
        // threw away the only thing known about where the pointer was asked to go,
        // and left the operator with "X=?, Y=?" on a command that had in fact
        // landed. The flag is what keeps the distinction: this is the requested
        // coordinate, not an observed one, and no consumer may treat it as
        // measured.
        MousePosition { x: want.x, y: want.y, captured: false, known: true }
    }

    // Execute a structured argv command directly — no shell, so typed text can never
    // be interpreted as shell syntax (F5). `human_command` drives action parsing and
    // the recorded string.
    async fn execute_command_argv(
        &self,
        argv: &[String],
        human_command: &str,
    ) -> (Result<String, String>, MousePosition, ActionDetails) {
        let action = self.parse_action_details(human_command);

        // Validate once and keep the plan: the expected end position and any button
        // transition are read from it, so neither can disagree with the grammar
        // about what a token meant.
        let plan = match argv_policy::validate(argv) {
            Ok(plan) => plan,
            Err(e) => {
                warn!("Blocked command {:?}: {}", argv, e);
                return (
                    Err(e),
                    MousePosition { x: 0, y: 0, captured: false, known: false },
                    action,
                );
            }
        };
        let expected = plan.expected_pos();
        let transition = plan.button_transition();
        // Read before `run_plan` consumes the plan.
        let deferred_arrival = plan.pointer_arrival_is_deferred();

        // A command that names no coordinate is verified against the cursor not
        // having moved, so the "before" sample has to be taken before it runs.
        let before = if action.is_mouse && expected.is_none() {
            Some(self.capture_mouse_position().await)
        } else {
            None
        };

        let result = self.run_plan(plan).await;
        if result.is_ok() {
            self.record_button_transition(transition, expected).await;
        }
        let position = self
            .capture_position_if_mouse(&action, result.is_ok(), expected, before, deferred_arrival)
            .await;
        (result, position, action)
    }

    // Update the held-button tracker after a command executed successfully.
    async fn record_button_transition(
        &self,
        transition: Option<argv_policy::ButtonTransition>,
        at: Option<argv_policy::ExpectedPos>,
    ) {
        let Some(transition) = transition else { return };
        let name = transition.button.as_str().to_string();
        let mut held = self.held_buttons.write().await;
        if transition.down {
            let at = at.map(|p| (p.x, p.y));
            held.insert(
                name.clone(),
                HeldButton { at, since: std::time::Instant::now() },
            );
            debug!("Tracking held {} button at {:?}", name, at);
        } else {
            held.remove(&name);
        }
    }

    // Render outstanding holds for the response metadata: "left@900,700:7".
    async fn held_buttons_summary(&self) -> String {
        let held = self.held_buttons.read().await;
        let mut entries: Vec<String> = held
            .iter()
            .map(|(name, b)| {
                let at = match b.at {
                    Some((x, y)) => format!("{},{}", x, y),
                    None => "?".to_string(),
                };
                format!("{}@{}:{}", name, at, b.since.elapsed().as_secs())
            })
            .collect();
        entries.sort();
        entries.join(";")
    }

    // The argv that releases a button on this platform. Goes back through the
    // grammar like any other action, so the shutdown path is not a way around it.
    //
    // With no recorded coordinate the release happens where the cursor already is.
    // Both the macOS and Windows forms move before releasing, so substituting an
    // origin would drag whatever is held to the corner.
    fn release_argv(button: argv_policy::MouseButton, at: Option<(i32, i32)>) -> Vec<String> {
        if cfg!(target_os = "macos") {
            let target = match at {
                Some((x, y)) => format!("du:{},{}", x, y),
                None => "du:.".to_string(),
            };
            vec!["cliclick".to_string(), target]
        } else if cfg!(target_os = "windows") {
            let content = match at {
                Some((x, y)) => format!("{} {} release", x, y),
                None => "here release".to_string(),
            };
            vec![
                "__write__".to_string(),
                r"C:\mouse_cmd.txt".to_string(),
                content,
            ]
        } else {
            let n = match button {
                argv_policy::MouseButton::Left => "1",
                argv_policy::MouseButton::Middle => "2",
                argv_policy::MouseButton::Right => "3",
            };
            vec![
                Self::linux_backend().to_string(),
                "mouseup".to_string(),
                n.to_string(),
            ]
        }
    }

    // Release every tracked button. Called on every agent-exit path.
    //
    // This is the one place the agent actuates without being asked. It releases only
    // buttons it recorded going down, and it cannot be recorded as a step: by the
    // time it runs the command stream is closed. That is a deliberate trade — a
    // button left physically down corrupts every step of whatever runs next, while
    // an unrecorded release happens after the session has already ended — so it is
    // logged loudly instead.
    async fn release_held_buttons(&self) {
        let outstanding: Vec<(String, HeldButton)> = {
            let held = self.held_buttons.read().await;
            held.iter().map(|(k, v)| (k.clone(), v.clone())).collect()
        };
        if outstanding.is_empty() {
            return;
        }

        for (name, button) in outstanding {
            let kind = match name.as_str() {
                "middle" => argv_policy::MouseButton::Middle,
                "right" => argv_policy::MouseButton::Right,
                _ => argv_policy::MouseButton::Left,
            };
            let argv = Self::release_argv(kind, button.at);
            let outcome = self.run_argv(&argv).await;
            warn!(
                "Auto-released {} button held at {} for {}s during shutdown \
                 ({}). This release is NOT recorded — the command stream is closed.",
                name,
                match button.at {
                    Some((x, y)) => format!("({}, {})", x, y),
                    None => "the current position".to_string(),
                },
                button.since.elapsed().as_secs(),
                match &outcome {
                    Ok(_) => "ok".to_string(),
                    Err(e) => format!("failed: {}", e),
                }
            );
        }
        self.held_buttons.write().await.clear();
    }

    // Run an argv vector directly (no shell). The vector is first checked against the
    // actuation grammar in argv_policy, which constrains sub-commands and arguments —
    // an argv[0] allow-list alone would still permit `xdotool exec` and free-form
    // `osascript -e`. Used by paths that have not already validated, such as the
    // shutdown auto-release.
    async fn run_argv(&self, argv: &[String]) -> Result<String, String> {
        let plan = argv_policy::validate(argv).inspect_err(|e| {
            warn!("Blocked command {:?}: {}", argv, e);
        })?;
        self.run_plan(plan).await
    }

    // Execute an already-validated plan.
    async fn run_plan(&self, plan: argv_policy::Plan) -> Result<String, String> {
        match plan {
            // Windows AutoHotkey file-drop: write content directly, no `cmd /c echo`.
            argv_policy::Plan::Write { path, content } => {
                std::fs::write(&path, &content).map_err(|e| format!("Write error: {}", e))?;
                Ok(format!("Executed: {}", content))
            }
            argv_policy::Plan::Run { bin, args } => {
                #[cfg(target_os = "macos")]
                if let Some(dest) = Self::glide_destination(bin, &args) {
                    return self.glide_macos(dest.0, dest.1);
                }
                self.spawn_actuation(bin, &args)?;
                Ok("ok".to_string())
            }
            // Focus click, then an AppleScript key-repeat loop. Both scripts are
            // composed here, so the client only ever supplies the bounded parameters.
            argv_policy::Plan::Scroll {
                click,
                key_code,
                amount,
                modifiers,
            } => {
                // The focus click stays unmodified. It exists only to give the window
                // the keys, and holding Cmd through it would make it a Cmd-click —
                // changing the selection before the scroll even starts.
                self.spawn_actuation(
                    argv_policy::Bin::Cliclick,
                    &[click, "w:50".to_string()],
                )?;
                let key_line = if modifiers.is_empty() {
                    format!("key code {}", key_code)
                } else {
                    format!("key code {} using {{{}}}", key_code, modifiers.join(", "))
                };
                self.spawn_actuation(
                    argv_policy::Bin::Osascript,
                    &[
                        "-e".to_string(),
                        format!("tell application \"System Events\" to repeat {} times", amount),
                        "-e".to_string(),
                        key_line,
                        "-e".to_string(),
                        "delay 0.02".to_string(),
                        "-e".to_string(),
                        "end repeat".to_string(),
                    ],
                )?;
                Ok("ok".to_string())
            }
            argv_policy::Plan::MiddleClick { click, flags } => {
                // cliclick cannot middle-click, so this posts the CGEvent directly
                // through JXA's Objective-C bridge — a tool already installed, rather
                // than a new dependency or a compiled helper.
                //
                // The script is composed here, and every value interpolated into it is
                // an integer this agent parsed: the coordinates from a validated
                // cliclick point token and the flags from a closed list of modifier
                // names. No client-supplied text reaches it, which is the same
                // property the scroll path holds and the reason neither accepts a
                // script over the wire.
                //
                // Constants are numeric rather than named so a gap in the bridge's
                // metadata cannot silently resolve to undefined and post nothing:
                //   25 kCGEventOtherMouseDown   26 kCGEventOtherMouseUp
                //    2 kCGMouseButtonCenter      0 kCGHIDEventTap
                let point = match click.strip_prefix("c:") {
                    // The `here` form: read the cursor rather than moving it.
                    Some(".") | None => {
                        "$.CGEventGetLocation($.CGEventCreate($()))".to_string()
                    }
                    Some(coords) => {
                        let (x, y) = coords.split_once(',').ok_or_else(|| {
                            format!("middle click: malformed point '{}'", click)
                        })?;
                        let x: i32 = x.parse().map_err(|_| {
                            format!("middle click: malformed x in '{}'", click)
                        })?;
                        let y: i32 = y.parse().map_err(|_| {
                            format!("middle click: malformed y in '{}'", click)
                        })?;
                        format!("$.CGPointMake({}, {})", x, y)
                    }
                };
                let script = format!(
                    "ObjC.import('CoreGraphics');\
                     var p = {point};\
                     var d = $.CGEventCreateMouseEvent($(), 25, p, 2);\
                     $.CGEventSetFlags(d, {flags});\
                     $.CGEventPost(0, d);\
                     var u = $.CGEventCreateMouseEvent($(), 26, p, 2);\
                     $.CGEventSetFlags(u, {flags});\
                     $.CGEventPost(0, u);"
                );
                self.spawn_actuation(
                    argv_policy::Bin::Osascript,
                    &["-l".to_string(), "JavaScript".to_string(), "-e".to_string(), script],
                )?;
                Ok("ok".to_string())
            }
        }
    }

    /// The destination of a plain pointer move, when smoothing should replace it.
    ///
    /// Only a cliclick invocation whose entire argument list is one `m:X,Y` token
    /// qualifies. That is exactly what the macOS builder emits for `<x> <y> move`,
    /// and restricting it to that shape is what keeps this from touching a chain:
    /// `kd:ctrl c:400,400 ku:ctrl` holds a modifier across the click, and replacing
    /// its middle token with a glide would drop the bracket and leave the modifier
    /// down. A click still jumps; only a move glides.
    ///
    /// Reading the switch here rather than in the controller is deliberate. The
    /// builder is stateless argv construction and cannot know where the pointer is,
    /// so it cannot compute a path; the agent runs on the machine holding the
    /// pointer and can. It also puts the setting in the same place Windows keeps
    /// it - an environment variable on the box being driven - so one switch means
    /// the same thing on both platforms, and the command grammar is untouched:
    /// `700 300 move` is recorded identically whether it glides or jumps.
    #[cfg(target_os = "macos")]
    fn glide_destination(bin: argv_policy::Bin, args: &[String]) -> Option<(i32, i32)> {
        if !matches!(bin, argv_policy::Bin::Cliclick) || args.len() != 1 {
            return None;
        }
        if std::env::var_os("CC_SMOOTH_MOVE").is_none() {
            return None;
        }
        let (x, y) = args[0].strip_prefix("m:")?.split_once(',')?;
        Some((x.parse().ok()?, y.parse().ok()?))
    }

    /// Travel to (x, y) as a paced sequence of posted mouse-moved events.
    ///
    /// The timing curve is minimum-jerk, 10t^3 - 15t^4 + 6t^5, and the constants
    /// match the Linux portal path exactly, so a glide has one velocity profile
    /// across platforms rather than each backend getting whatever its own toolkit
    /// calls smooth.
    ///
    /// Posted through JXA for the same reason the middle click is: cliclick has no
    /// way to pace a chain finely enough, and osascript is already installed. Every
    /// value interpolated into the script is an integer parsed here - the
    /// destination from a validated cliclick token - so no client-supplied text
    /// reaches it. The origin is read inside the script rather than passed in,
    /// which is what makes a stateless builder sufficient.
    ///
    /// Numeric constants, matching the middle-click path's reasoning that a gap in
    /// the bridge's metadata must not silently resolve to undefined:
    ///   5 kCGEventMouseMoved   0 kCGHIDEventTap   0 kCGMouseButtonLeft
    #[cfg(target_os = "macos")]
    fn glide_macos(&self, x: i32, y: i32) -> Result<String, String> {
        const STEP_HZ: f64 = 120.0;
        const MIN_MS: f64 = 120.0;
        const MAX_MS: f64 = 900.0;
        const MS_PER_PX: f64 = 0.55;

        let script = format!(
            "ObjC.import('CoreGraphics');\
             ObjC.import('Foundation');\
             var s = $.CGEventGetLocation($.CGEventCreate($()));\
             var x0 = s.x, y0 = s.y, x1 = {x}, y1 = {y};\
             var d = Math.sqrt((x1-x0)*(x1-x0) + (y1-y0)*(y1-y0));\
             if (d <= 1) {{ d = 0; }}\
             var dur = Math.min({MAX_MS}, {MIN_MS} + d * {MS_PER_PX});\
             var n = Math.max(2, Math.round(dur / (1000 / {STEP_HZ})));\
             var gap = dur / n / 1000;\
             for (var i = 1; i <= n; i++) {{\
               var t = i / n;\
               var e = t*t*t*(10 + t*(-15 + 6*t));\
               var px = (i === n) ? x1 : x0 + (x1-x0)*e;\
               var py = (i === n) ? y1 : y0 + (y1-y0)*e;\
               $.CGEventPost(0, $.CGEventCreateMouseEvent($(), 5, $.CGPointMake(px, py), 0));\
               $.NSThread.sleepForTimeInterval(gap);\
             }}"
        );
        self.spawn_actuation(
            argv_policy::Bin::Osascript,
            &["-l".to_string(), "JavaScript".to_string(), "-e".to_string(), script],
        )?;
        Ok("ok".to_string())
    }

    // Spawn a validated actuation binary. Never goes through a shell.
    fn spawn_actuation(&self, bin: argv_policy::Bin, args: &[String]) -> Result<(), String> {
        let program: String = match bin {
            argv_policy::Bin::Xdotool => "xdotool".to_string(),
            argv_policy::Bin::CcWayland => "cc-wayland-actuate".to_string(),
            argv_policy::Bin::Osascript => "osascript".to_string(),
            // Resolve cliclick to the path probed at startup (macOS-only field).
            argv_policy::Bin::Cliclick => {
                #[cfg(target_os = "macos")]
                {
                    self.cliclick_path
                        .clone()
                        .unwrap_or_else(|| "cliclick".to_string())
                }
                #[cfg(not(target_os = "macos"))]
                {
                    "cliclick".to_string()
                }
            }
        };

        let mut cmd = ProcessCommand::new(&program);
        cmd.args(args);
        // xdotool needs DISPLAY; harmless for the others.
        let display = std::env::var("DISPLAY").unwrap_or_else(|_| ":0".to_string());
        cmd.env("DISPLAY", display);

        let output = cmd.output().map_err(|e| {
            error!("Failed to execute {}: {}", program, e);
            format!("Execution error: {}", e)
        })?;

        let stderr = String::from_utf8_lossy(&output.stderr).to_string();

        if !output.status.success() {
            error!("Command failed: {}", stderr);
            return Err(stderr);
        }

        // xdotool exits 0 after dropping a key it cannot resolve, logging only
        // "No such key name '<x>'. Ignoring it." on stderr. The remaining modifiers
        // are still delivered, so the caller sees a successful command that did
        // something other than what was asked. Treat the warning as a failure.
        if stderr.contains("No such key name") {
            error!("Command dropped a key: {}", stderr);
            return Err(stderr.trim().to_string());
        }

        Ok(())
    }
}

// Implement the gRPC service
#[tonic::async_trait]
impl AgentService for AgentServiceImpl {
    async fn get_info(
        &self,
        _request: Request<InfoRequest>,
    ) -> Result<Response<AgentInfo>, Status> {
        info!("Agent info requested");
        
        Ok(Response::new(AgentInfo {
            os: self.os_type as i32,
            os_version: self.os_version.clone(),
            capabilities: self.capabilities.clone(),
            agent_version: env!("CARGO_PKG_VERSION").to_string(),
        }))
    }
    
    // Retired. ExecuteRequest carries only a shell string; commands arrive over the
    // server stream as structured argv and are handled by execute_command_argv.
    // The agent binds no gRPC listener, so this exists only to satisfy the trait.
    async fn execute(
        &self,
        _request: Request<ExecuteRequest>,
    ) -> Result<Response<ExecuteResponse>, Status> {
        Err(Status::unimplemented(
            "Execute is retired: commands are delivered as argv over the agent stream",
        ))
    }

    async fn ping(
        &self,
        _request: Request<PingRequest>,
    ) -> Result<Response<PongResponse>, Status> {
        Ok(Response::new(PongResponse { alive: true }))
    }
}

// Main function to start the agent
#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    tracing_subscriber::fmt::init();
    
    info!("Control Center Agent v{}", env!("CARGO_PKG_VERSION"));
    info!("Starting Agent...");
    
    // Create agent service (keeps all execution logic)
    let service = AgentServiceImpl::new();
    let os_type = service.os_type;
    let os_version = service.os_version.clone();
    let capabilities = service.capabilities.clone();
    
    // Read server connection info from environment
    let server_host = std::env::var("AGENT_SERVER_HOST")
        .unwrap_or_else(|_| "127.0.0.1".to_string());
    let server_port = std::env::var("AGENT_SERVER_PORT")
        .unwrap_or_else(|_| "50051".to_string())
        .parse()
        .unwrap_or(50051);
    
    info!("Connecting to server at {}:{}...", server_host, server_port);
    
    // Build agent identity
    let agent_identity = identity::build_agent_identity(
        os_type,
        os_version,
        capabilities,
        env!("CARGO_PKG_VERSION").to_string(),
    );
    
    // Validate identity
    if let Err(e) = identity::validate_agent_identity(&agent_identity) {
        error!("Invalid agent identity: {}", e);
        return Err(e.into());
    }
    
    // Create connection manager
    let auth_token = std::env::var("CONTROL_CENTER_TOKEN").ok();
    let connection_manager = connection::ConnectionManager::new(
        server_host,
        server_port,
        agent_identity,
        auth_token.clone(),
    );
    
    // Connect and register
        match connection_manager.connect_and_register().await {
        Ok(mut client) => {
            info!("✓ Ready to accept commands");
            
            let agent_start_time = std::time::Instant::now();
            let commands_executed = std::sync::Arc::new(tokio::sync::RwLock::new(0u64));
            let commands_failed = std::sync::Arc::new(tokio::sync::RwLock::new(0u64));
            let (agent_tx, agent_rx) = tokio::sync::mpsc::channel(100);
            
            // Start bidirectional stream with server
            info!("Starting bidirectional stream with server...");
            let request_stream = tokio_stream::wrappers::ReceiverStream::new(agent_rx);

            // Authenticate the stream: attach the agent JWT as Bearer metadata so the
            // server can verify and bind it (F2).
            let mut stream_request = Request::new(request_stream);
            if let Some(token) = &auth_token {
                match format!("Bearer {}", token).parse() {
                    Ok(value) => { stream_request.metadata_mut().insert("authorization", value); }
                    Err(e) => { error!("Invalid CONTROL_CENTER_TOKEN for stream metadata: {}", e); }
                }
            }

            let response = match client.agent_stream(stream_request).await {
                Ok(resp) => resp,
                Err(e) => {
                    error!("Failed to start agent stream: {}", e);
                    return Err(e.into());
                }
            };
            
            let mut server_stream = response.into_inner();
            info!("✓ Bidirectional stream established");
            
            // Get connection ID for heartbeats
            let connection_id = connection_manager.get_connection_id().await
                .ok_or_else(|| {
                    error!("No connection ID available");
                    "No connection ID"
                })?;
            
            // Spawn heartbeat sender with REAL metrics
            let heartbeat_tx = agent_tx.clone();
            let heartbeat_conn_id = connection_id.clone();
            let heartbeat_start_time = agent_start_time;
            let heartbeat_executed = commands_executed.clone();
            let heartbeat_failed = commands_failed.clone();
            
            tokio::spawn(async move {
                let mut interval = tokio::time::interval(tokio::time::Duration::from_secs(30));
                loop {
                    interval.tick().await;
                    
                    // Calculate REAL uptime
                    let uptime_seconds = heartbeat_start_time.elapsed().as_secs();
                    
                    // Get REAL command counts
                    let executed = *heartbeat_executed.read().await;
                    let failed = *heartbeat_failed.read().await;
                    
                    let heartbeat = proto::AgentHeartbeat {
                        connection_id: heartbeat_conn_id.clone(),
                        timestamp: chrono::Utc::now().timestamp(),
                        status: Some(proto::AgentStatus {
                            ready: true,
                            commands_executed: executed,
                            commands_failed: failed,
                            uptime_seconds: uptime_seconds as i64,
                            system_info: std::collections::HashMap::new(),
                        }),
                        current_command_id: None,
                    };
                    
                    let agent_msg = proto::AgentMessage {
                        connection_id: heartbeat_conn_id.clone(),
                        payload: Some(proto::agent_message::Payload::Heartbeat(heartbeat)),
                    };
                    
                    if heartbeat_tx.send(agent_msg).await.is_err() {
                        warn!("Failed to send heartbeat, stream may be closed");
                        break;
                    }
                    
                    debug!(
                        "Sent heartbeat - uptime: {}s, executed: {}, failed: {}",
                        uptime_seconds, executed, failed
                    );
                }
            });
            
            info!("Agent running. Press Ctrl+C to stop.");
            info!("Listening for commands from server...");
            info!("Full tracking enabled (commands, uptime, execution times)");

            // No button state carries into a freshly registered session. Redundant in
            // a process that connects once, but it keeps the invariant explicit if a
            // reconnect loop is ever added around this block.
            service.held_buttons.write().await.clear();


            // Both interactive (SIGINT) and supervised (SIGTERM) shutdowns have to
            // reach the cleanup below. SIGTERM is what a service manager, a container
            // stop and `Popen.terminate()` send; leaving it to the default handler
            // killed the process outright, so a button held at that moment stayed
            // physically down.
            let mut shutdown_signal = Box::pin(async {
                #[cfg(unix)]
                {
                    match tokio::signal::unix::signal(
                        tokio::signal::unix::SignalKind::terminate(),
                    ) {
                        Ok(mut sigterm) => tokio::select! {
                            _ = tokio::signal::ctrl_c() => "SIGINT",
                            _ = sigterm.recv() => "SIGTERM",
                        },
                        Err(e) => {
                            warn!("Could not install SIGTERM handler: {}", e);
                            let _ = tokio::signal::ctrl_c().await;
                            "SIGINT"
                        }
                    }
                }
                #[cfg(not(unix))]
                {
                    let _ = tokio::signal::ctrl_c().await;
                    "Ctrl+C"
                }
            });

            // Main command loop - listen for messages from server
            loop {
                tokio::select! {
                    // Handle an interactive or supervised shutdown
                    signal = &mut shutdown_signal => {
                        info!("Received {}, shutting down...", signal);

                        // Send disconnect message
                        let disconnect = proto::DisconnectNotice {
                            reason: format!("Agent received {}", signal),
                            timestamp: chrono::Utc::now().timestamp(),
                            graceful: true,
                        };
                        
                        let agent_msg = proto::AgentMessage {
                            connection_id: connection_id.clone(),
                            payload: Some(proto::agent_message::Payload::Disconnect(disconnect)),
                        };
                        
                        let _ = agent_tx.send(agent_msg).await;
                        
                        break;
                    }
                    
                    // Handle incoming messages from server
                    server_msg = server_stream.message() => {
                        match server_msg {
                            Ok(Some(msg)) => {
                                match msg.payload {
                                    Some(proto::server_message::Payload::CommandRequest(cmd_req)) => {
                                        let command_id = cmd_req.id.clone();

                                        // Track command execution time
                                        let cmd_start_time = std::time::Instant::now();

                                        // Structured argv is the only accepted form; the legacy
                                        // shell-string field is rejected without executing.
                                        let human_cmd = cmd_req.human_command.clone();
                                        let malformed = if cmd_req.argv.is_empty() {
                                            Some("argv is required: the legacy shell command field is no longer accepted")
                                        } else if human_cmd.is_empty() {
                                            Some("human_command is required alongside argv")
                                        } else {
                                            None
                                        };

                                        debug!("Received command: {} (ID: {})", human_cmd, command_id);

                                        let (result, position, action) = match malformed {
                                            Some(reason) => {
                                                warn!("Rejected command {}: {}", command_id, reason);
                                                (
                                                    Err(reason.to_string()),
                                                    MousePosition { x: 0, y: 0, captured: false, known: false },
                                                    service.parse_action_details(&human_cmd),
                                                )
                                            }
                                            None => {
                                                service.execute_command_argv(&cmd_req.argv, &human_cmd).await
                                            }
                                        };

                                        let execution_time = cmd_start_time.elapsed();

                                        // Ground truth for the recorded event: what actually
                                        // ran, independent of the caller-supplied
                                        // human_command that drives the display string.
                                        let mut executed_meta = std::collections::HashMap::new();
                                        executed_meta.insert(
                                            "argv".to_string(),
                                            cmd_req.argv.join("\u{1f}"),
                                        );
                                        // Buttons still down, so the console can warn
                                        // rather than let a hold go unnoticed. Uses the
                                        // existing metadata map — no new RPC, and so no
                                        // new authorisation decision.
                                        executed_meta.insert(
                                            "held_buttons".to_string(),
                                            service.held_buttons_summary().await,
                                        );

                                        // Build response and update counters
                                        let response = match result {
                                            Ok(_) => {
                                                *commands_executed.write().await += 1;

                                                let message = service.build_detailed_message(
                                                    &action, &position, &human_cmd,
                                                );

                                                debug!(
                                                    "Command {} executed successfully (time: {:?})",
                                                    command_id,
                                                    execution_time
                                                );

                                                proto::CommandResponse {
                                                    id: command_id.clone(),
                                                    success: true,
                                                    message,
                                                    execution_time_ms: execution_time.as_millis() as i64,
                                                    mouse_x: if position.known { Some(position.x) } else { None },
                                                    mouse_y: if position.known { Some(position.y) } else { None },
                                                    position_captured: Some(position.captured),
                                                    metadata: executed_meta,
                                                }
                                            }
                                            Err(e) => {
                                                // Increment failure counter
                                                *commands_failed.write().await += 1;

                                                error!(
                                                    "Command {} failed: {} (time: {:?})",
                                                    command_id,
                                                    e,
                                                    execution_time
                                                );

                                                proto::CommandResponse {
                                                    id: command_id.clone(),
                                                    success: false,
                                                    message: format!("Execution error: {}", e),
                                                    execution_time_ms: execution_time.as_millis() as i64,
                                                    mouse_x: None,
                                                    mouse_y: None,
                                                    position_captured: None,
                                                    metadata: executed_meta,
                                                }
                                            }
                                        };
                                        
                                        // Send response back to server
                                        let agent_msg = proto::AgentMessage {
                                            connection_id: connection_id.clone(),
                                            payload: Some(proto::agent_message::Payload::CommandResponse(response)),
                                        };
                                        
                                        if agent_tx.send(agent_msg).await.is_err() {
                                            error!("Failed to send command response, stream closed");
                                            break;
                                        }
                                        
                                        debug!("Sent command response for {}", command_id);
                                    }
                                    
                                    Some(proto::server_message::Payload::Heartbeat(_heartbeat)) => {
                                        debug!("Received heartbeat from server");
                                        // Server is alive, no action needed
                                    }
                                    
                                    Some(proto::server_message::Payload::Disconnect(notice)) => {
                                        warn!("Server requested disconnect: {}", notice.reason);
                                        break;
                                    }
                                    
                                    Some(proto::server_message::Payload::ConfigUpdate(config)) => {
                                        debug!("Received config update from server");
                                        // Log the settings being updated
                                        for (key, value) in config.settings.iter() {
                                            debug!("Config update: {} = {}", key, value);
                                        }
                                        // Config updates can be implemented in the future if needed
                                    }
                                    
                                    None => {
                                        warn!("Received message with no payload");
                                    }
                                }
                            }
                            Ok(None) => {
                                info!("Server closed stream");
                                break;
                            }
                            Err(e) => {
                                error!("Stream error: {}", e);
                                break;
                            }
                        }
                    }
                }
            }
            
            // Every exit path from the command loop lands here — Ctrl+C, a server
            // disconnect notice, the stream closing, and a stream error — so this is
            // the single place a button left down can be cleaned up.
            service.release_held_buttons().await;

            // Print final statistics on shutdown
            let final_executed = *commands_executed.read().await;
            let final_failed = *commands_failed.read().await;
            let final_uptime = agent_start_time.elapsed();
            
            info!("═══════════════════════════════════════");
            info!("Agent Shutdown Statistics");
            info!("═══════════════════════════════════════");
            info!("  Uptime: {:.2}h ({:.0}s)", 
                final_uptime.as_secs_f64() / 3600.0,
                final_uptime.as_secs_f64());
            info!("  Commands executed: {}", final_executed);
            info!("  Commands failed: {}", final_failed);
            info!("  Success rate: {:.2}%", 
                if final_executed + final_failed > 0 {
                    (final_executed as f64 / (final_executed + final_failed) as f64) * 100.0
                } else {
                    0.0
                });
            info!("═══════════════════════════════════════");
        }
        Err(e) => {
            error!("Failed to connect: {}", e);
            return Err(e);
        }
    }
    
    Ok(())
}

// Unit tests for OS detection and command validation
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn only_the_wayland_reader_reports_its_own_staleness() {
        // The `position` exemption from the before/after agreement check is gated on
        // this, and getting it wrong is not visible in a passing suite: an
        // over-broad answer silently removes the only staleness signal `position`
        // has on X11, which is what shipped in 2.0.0 and was caught by measurement
        // rather than by a test.
        //
        // The Wayland helper is the only reader that distinguishes "I read a value"
        // from "the value I read is current" — it emits POSITION_VERIFIED=0 when
        // XWayland is stuck over a native-Wayland surface.
        assert!(AgentServiceImpl::reader_reports_staleness("cc-wayland-actuate"));

        // Everything else reports captured=true whenever a value parsed at all.
        for reader in ["xdotool", "cliclick", "", "cc-wayland", "CC-WAYLAND-ACTUATE"] {
            assert!(
                !AgentServiceImpl::reader_reports_staleness(reader),
                "{reader:?} does not self-report staleness and must keep the \
                 before/after check"
            );
        }
    }

    #[test]
    fn the_exemption_follows_the_one_backend_selector() {
        // Not a second detector: whatever `linux_backend` picks is what decides the
        // exemption. On a non-Linux target the fallback is xdotool, so macOS and
        // Windows keep the check — neither cliclick nor the registry reports
        // staleness either.
        let live = AgentServiceImpl::reader_reports_staleness(AgentServiceImpl::linux_backend());
        assert_eq!(live, AgentServiceImpl::linux_backend() == "cc-wayland-actuate");
        if !cfg!(target_os = "linux") {
            assert!(!live, "only the Linux Wayland path may take the exemption");
        }
    }

    #[test]
    fn test_os_detection() {
        let (_os_type, version) = AgentServiceImpl::detect_os_version();
        assert!(!version.is_empty());
        assert!(!version.contains("Unknown") || cfg!(debug_assertions));
    }

    #[test]
    fn glide_budget_covers_ahk_cap() {
        // The deferred budget must let its last re-read fall past the moment a Windows
        // smooth move/drag finishes gliding, or a glide that landed perfectly reports
        // X=?. Arrival is the glide cap plus one watcher poll after the write; the last
        // read is settle + budget*interval. This pins the two together so raising the
        // .ahk SMOOTH_MAX_MS without raising the budget fails the build rather than
        // silently reintroducing the X=? readback.
        let settle_ms: u64 = 20; // Windows non-here settle
        let last_read_ms =
            settle_ms + DEFERRED_POSITION_REREADS as u64 * POSITION_REREAD_INTERVAL_MS;
        let worst_arrival_ms = AHK_GLIDE_MAX_MS + 10; // + one 10ms watcher poll
        assert!(
            last_read_ms >= worst_arrival_ms,
            "deferred budget's last read is {last_read_ms}ms but a glide can still be \
             arriving at {worst_arrival_ms}ms; raise DEFERRED_POSITION_REREADS"
        );
    }

    fn service(os_type: OsType) -> AgentServiceImpl {
        AgentServiceImpl {
            os_type,
            os_version: "test".to_string(),
            capabilities: Vec::new(),
            #[cfg(target_os = "macos")]
            cliclick_path: None,
            held_buttons: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    #[test]
    fn a_single_brace_token_still_unwraps() {
        let svc = service(OsType::Windows);
        assert_eq!(svc.format_keys_for_display("{LWin}"), "LWin");
        assert_eq!(svc.format_keys_for_display("{Enter}"), "Return");
        assert_eq!(svc.format_keys_for_display("^{Plus}"), "Ctrl+Plus");
    }

    #[test]
    fn an_explicit_down_up_sequence_keeps_its_braces() {
        // It starts with '{' and ends with '}', so the old unwrap turned
        // "{Ctrl down}s{Ctrl up}" into "Ctrl down}s{Ctrl up": an unbalanced brace
        // that the Memory Archive converter panicked on, voiding the capture
        // session. Any caller can send this form, so the guard belongs here and not
        // only in the Windows builder that used to produce it.
        let svc = service(OsType::Windows);
        for keys in [
            "{Ctrl down}s{Ctrl up}",
            "{Ctrl down}{Tab}{Ctrl up}",
            "{Ctrl down}{Shift down}{Esc}{Shift up}{Ctrl up}",
        ] {
            let shown = svc.format_keys_for_display(keys);
            assert_eq!(shown, keys, "the sequence was rewritten");
            assert_eq!(
                shown.matches('{').count(),
                shown.matches('}').count(),
                "unbalanced braces in {:?}",
                shown
            );
        }
    }

    // ---- typed text is reported exactly as issued -------------------------
    // S026: the record read "Typed: osascript -e \" because the agent re-derived the
    // payload from the AppleScript, ending it at the first `"` — which was the second
    // half of an escape sequence. a0bf3fe deleted that extractor; the command now
    // arrives on the wire and only the verb is trimmed. This pins that.

    const QUOTED_PAYLOADS: &[&str] = &[
        r#"printf "Title\nBody" > note.txt"#,
        r#"say "hi""#,
        r#"osascript -e "tell app \"X\" to y""#,
        r"ends with a backslash \",
        r#"both "quoted" and trailing \"#,
    ];

    fn typed(svc: &AgentServiceImpl, command: &str) -> String {
        let action = svc.parse_action_details(command);
        let position = MousePosition { x: 0, y: 0, captured: false, known: false };
        svc.build_detailed_message(&action, &position, command)
    }

    #[test]
    fn typed_text_is_reported_byte_for_byte() {
        let svc = service(OsType::Macos);
        for payload in QUOTED_PAYLOADS {
            let message = typed(&svc, &format!("type {payload}"));
            assert_eq!(
                message,
                format!("Typed: {payload}"),
                "the payload was altered on the way to the record"
            );
            assert!(!message.ends_with('\\') || payload.ends_with('\\'));
        }
    }

    #[test]
    fn typed_text_is_not_cut_at_the_first_quote() {
        // The exact S026 signature, named separately so a regression identifies itself.
        let svc = service(OsType::Macos);
        let message = typed(
            &svc,
            r#"type osascript -e "tell application "System Events" to set picture of every desktop to "/Users/agentuser/corpus-seed/wall-A.jpg"""#,
        );
        assert_ne!(message, r"Typed: osascript -e \");
        assert!(message.contains("wall-A.jpg"), "{message:?}");
    }

    #[test]
    fn leading_whitespace_in_typed_text_is_not_carried_into_the_record() {
        // Documented boundary, not an endorsement. The builders split the command at
        // the first space (`split(maxsplit=1)`), so "type   x" actuates two leading
        // spaces, while the verb trim here drops them from the record. Reachable from
        // the console, which strips the line but not the gap after the verb. Pinned so
        // that tightening it is a deliberate change rather than an accident.
        let svc = service(OsType::Macos);
        assert_eq!(typed(&svc, "type   x"), "Typed: x");
    }

    // ---- modifier-held pointer actions -------------------------------------
    // A Cmd-click adds to a selection where a plain click replaces it, so the two are
    // different gestures. The record is composed here, not in the controller: before
    // the prefix was split off the verb, "770 310 #left" failed the `is_mouse` match
    // and was stored as "Typed: 770 310 #left" — a pointer action recorded as text,
    // with no coordinate captured.

    fn recorded(svc: &AgentServiceImpl, command: &str, x: i32, y: i32) -> String {
        let action = svc.parse_action_details(command);
        let position = MousePosition { x, y, captured: true, known: true };
        svc.build_detailed_message(&action, &position, command)
    }

    #[test]
    fn a_modifier_held_click_names_the_modifier_in_the_record() {
        let svc = service(OsType::Macos);
        assert_eq!(
            recorded(&svc, "770 310 #left", 770, 310),
            "Cmd+Left-clicked at X=770, Y=310"
        );
        assert_eq!(
            recorded(&svc, "770 310 #+left", 770, 310),
            "Cmd+Shift+Left-clicked at X=770, Y=310"
        );
        assert_eq!(
            recorded(&svc, "here +left", 12, 34),
            "Shift+Left-clicked at X=12, Y=34"
        );
        assert_eq!(
            recorded(&svc, "200 300 !drag 900 640", 900, 640),
            "Option+Dragged from X=200, Y=300 to X=900, Y=640"
        );
    }

    #[test]
    fn a_modified_pointer_action_is_still_a_pointer_action() {
        // `is_mouse` gates the position readback. If the prefix stayed on the verb the
        // command would report no coordinate at all, on top of the wrong wording.
        let svc = service(OsType::Macos);
        for command in ["770 310 #left", "here !double", "200 300 ^drag 900 640"] {
            let action = svc.parse_action_details(command);
            assert!(action.is_mouse, "{command:?} was not read as a mouse action");
            assert!(!action.modifiers.is_empty(), "{command:?} lost its modifier");
        }
    }

    #[test]
    fn the_modifier_name_follows_the_platform() {
        // The same symbol is Cmd on macOS and Super on Linux, as it already is for a
        // chord. One table drives both.
        assert_eq!(
            recorded(&service(OsType::Linux), "770 310 #left", 770, 310),
            "Super+Left-clicked at X=770, Y=310"
        );
        assert_eq!(
            recorded(&service(OsType::Windows), "770 310 !left", 770, 310),
            "Alt+Left-clicked at X=770, Y=310"
        );
    }

    #[test]
    fn an_unmodified_action_reads_exactly_as_before() {
        let svc = service(OsType::Macos);
        assert_eq!(recorded(&svc, "770 310 left", 770, 310), "Left-clicked at X=770, Y=310");
        // The doubled "at" is pre-existing and deliberately pinned, not endorsed: the
        // action-name table mixes conventions ("Left-clicked" without the preposition,
        // "Held button at" with it) and the format string appends " at X=…" to both.
        // Every hold, release and scroll step already in the corpus reads this way, so
        // correcting it is a record-format change for ma-core to agree to, not a
        // cleanup to slip in beside a feature.
        assert_eq!(recorded(&svc, "here hold", 5, 6), "Held button at at X=5, Y=6");
        assert_eq!(
            recorded(&svc, "200 300 drag 900 640", 900, 640),
            "Dragged from X=200, Y=300 to X=900, Y=640"
        );
        assert_eq!(recorded(&svc, "position", 1, 2), "Position: X=1, Y=2");
    }

    #[test]
    fn a_token_of_modifiers_alone_is_not_read_as_a_verb() {
        // The controller cannot emit this. If one ever arrives it must not resolve to
        // some default click — an unnamed gesture recorded as a real one is the
        // failure this whole path exists to prevent.
        let svc = service(OsType::Macos);
        let action = svc.parse_action_details("770 310 #");
        assert!(!action.is_mouse);
        assert!(action.modifiers.is_empty());
        assert_eq!(action.action_type, "#");
    }

    #[test]
    fn a_horizontal_scroll_is_recorded_as_a_scroll() {
        // scroll_left/scroll_right are macOS verbs the controller emits, but they were
        // missing from the mouse-verb match, so they recorded as "Typed: 960 540
        // scroll_left 3". Same defect class as the modifier prefix, found alongside it.
        let svc = service(OsType::Macos);
        assert_eq!(
            recorded(&svc, "960 540 scroll_left 3", 960, 540),
            "Scrolled left 3 notches at X=960, Y=540"
        );
        assert_eq!(
            recorded(&svc, "960 540 scroll_right 3", 960, 540),
            "Scrolled right 3 notches at X=960, Y=540"
        );
    }

    // ---- the scroll repeat count reaches the record -------------------------
    // "here scroll_down 5" and "here scroll_down 1" stored the same string, so a
    // captured scroll could not be replayed from the record (S074). The count was
    // always on the wire — human_command is the command as issued — and only the
    // rendering dropped it.

    #[test]
    fn a_scroll_records_how_far_it_scrolled() {
        let svc = service(OsType::Macos);
        assert_eq!(
            recorded(&svc, "here scroll_down 5", 770, 310),
            "Scrolled down 5 notches at X=770, Y=310"
        );
        assert_eq!(
            recorded(&svc, "960 540 scroll_up 3", 960, 540),
            "Scrolled up 3 notches at X=960, Y=540"
        );
        // Singular, matching the console echo's existing wording.
        assert_eq!(
            recorded(&svc, "here scroll_up 1", 770, 310),
            "Scrolled up 1 notch at X=770, Y=310"
        );
    }

    #[test]
    fn a_drag_records_every_point_it_visited() {
        // Each of these lost part of the path on hardware. A record that cannot
        // reproduce the gesture is the S074 failure: the step looks fine and replays
        // as something else.
        let svc = service(OsType::Macos);

        // The plain coordinate form is unchanged, byte for byte. Memory Archive's
        // converter already parses this wording, so the fix must not disturb it.
        assert_eq!(
            recorded(&svc, "500 400 drag 900 700", 900, 700),
            "Dragged from X=500, Y=400 to X=900, Y=700"
        );

        // Waypoints were never recorded, and the `via` token failed the old integer
        // parse so the origin was dropped with them.
        assert_eq!(
            recorded(&svc, "500 400 drag via 700 500 via 800 600 to 900 700", 900, 700),
            "Dragged from X=500, Y=400 via X=700, Y=500 via X=800, Y=600 to X=900, Y=700"
        );

        // The `here` form recorded "Dragged at X=…", one point, reading like a
        // stationary action. It names no origin because it has none to name — it
        // starts wherever the cursor is — but the destination is in the command.
        assert_eq!(
            recorded(&svc, "here drag 900 700", 900, 700),
            "Dragged to X=900, Y=700"
        );
        assert_eq!(
            recorded(&svc, "here drag via 700 500 to 900 700", 900, 700),
            "Dragged via X=700, Y=500 to X=900, Y=700"
        );

        // A trailing dwell is timing, not geometry, and must not be read as a point.
        assert_eq!(
            recorded(&svc, "500 400 drag 900 700 dwell 1200", 900, 700),
            "Dragged from X=500, Y=400 to X=900, Y=700"
        );

        // Modifiers still prefix the whole thing.
        assert_eq!(
            recorded(&svc, "500 400 #drag 900 700", 900, 700),
            "Cmd+Dragged from X=500, Y=400 to X=900, Y=700"
        );
    }

    #[test]
    fn the_click_alias_records_as_the_click_it_performs() {
        // `click` and `left` build the identical argv, so the same gesture must not
        // record two different ways. `click` had no arm in the phrase map and fell to
        // the generic case, which named neither a button nor a click — and carried a
        // doubled preposition from "Performed action at" + " at X=".
        let svc = service(OsType::Macos);
        assert_eq!(
            recorded(&svc, "770 310 click", 770, 310),
            "Left-clicked at X=770, Y=310"
        );
        assert_eq!(
            recorded(&svc, "770 310 click", 770, 310),
            recorded(&svc, "770 310 left", 770, 310),
        );
        assert_eq!(
            recorded(&svc, "here #click", 770, 310),
            "Cmd+Left-clicked at X=770, Y=310"
        );
    }

    #[test]
    fn every_mouse_verb_has_a_phrase_of_its_own() {
        // `click` reached the generic arm and recorded "Performed action at at X=…" —
        // a gesture named after nothing, for a verb the help text advertises. Rather
        // than test the generic arm (no verb reaches it now), assert the property that
        // failed: every verb `parse_action_details` classifies as a mouse action must
        // render as itself. A verb added to that list without a phrase fails here
        // instead of shipping an unnamed record.
        let svc = service(OsType::Macos);
        for command in [
            "770 310 left", "770 310 right", "770 310 middle", "770 310 double",
            "770 310 triple", "770 310 click", "770 310 move", "770 310 hold",
            "770 310 release", "500 400 drag 900 700",
            "770 310 scroll_up", "770 310 scroll_down",
            "770 310 scroll_left", "770 310 scroll_right",
            "position",
        ] {
            let action = svc.parse_action_details(command);
            assert!(action.is_mouse, "{command:?} is no longer a mouse action");
            let got = recorded(&svc, command, 770, 310);
            assert!(
                !got.contains("Performed action"),
                "{command:?} has no phrase of its own and recorded as {got:?}",
            );
        }
    }

    #[test]
    fn a_scroll_that_names_no_count_records_the_default() {
        // A command that names no count still scrolls DEFAULT_SCROLL_NOTCHES, and the
        // record says so. The record is the only surviving description of the gesture,
        // so a silent omission loses the count rather than being cautious about it —
        // and a countless record would replay differently against a backend whose
        // default had moved.
        let svc = service(OsType::Macos);
        assert_eq!(
            recorded(&svc, "here scroll_down", 770, 310),
            "Scrolled down 5 notches at X=770, Y=310"
        );
        assert_eq!(
            recorded(&svc, "960 540 scroll_down", 960, 540),
            "Scrolled down 5 notches at X=960, Y=540"
        );
        // A non-numeric token in the count position is not a count, so the default
        // applies — the same thing the backends do with it.
        assert_eq!(
            recorded(&svc, "here scroll_down fast", 770, 310),
            "Scrolled down 5 notches at X=770, Y=310"
        );
    }

    #[test]
    fn the_recorded_default_is_the_one_the_backends_apply() {
        // Guards the constant itself rather than a sentence built from it: if
        // DEFAULT_SCROLL_NOTCHES moves without the three backends moving with it, the
        // agent starts reporting a count that was never performed. The cross-backend
        // half of this lives in tests/unit/test_actuation_argv.py, which reads all
        // four sources including this file.
        assert_eq!(DEFAULT_SCROLL_NOTCHES, 5);
    }

    #[test]
    fn a_modified_scroll_records_both_the_modifier_and_the_count() {
        let svc = service(OsType::Macos);
        assert_eq!(
            recorded(&svc, "770 310 #scroll_down 3", 770, 310),
            "Cmd+Scrolled down 3 notches at X=770, Y=310"
        );
        assert_eq!(
            recorded(&svc, "here #+scroll_up 5", 770, 310),
            "Cmd+Shift+Scrolled up 5 notches at X=770, Y=310"
        );
    }

    #[test]
    fn a_canonical_windows_chord_reads_as_a_chord() {
        // What the fixed controller now reports: "press ^s" reaches the agent
        // verbatim, so the display string is the chord rather than the AHK wire form.
        let svc = service(OsType::Windows);
        assert_eq!(svc.format_keys_for_display("^s"), "Ctrl+S");
        assert_eq!(svc.format_keys_for_display("^+n"), "Ctrl+Shift+N");
        assert_eq!(svc.format_keys_for_display("!{Tab}"), "Alt+Tab");
    }
}
